(4360913, 628115, 87560, '<td valign="top">Yes--this one really does capture for me that peculiar quality of ice--it''s combination of clarity and blurriness. Nicely abstracted.</td>', 'Yes--this one really does capture for me that peculiar quality of ice--it''s combination of clarity and blurriness. Nicely abstracted.', '2008-01-04 17:02:09.000000', NULL, 1),
