(4361731, 626710, 62318, '<td valign="top">Wonderful sense of scale. Might be a tad blue in the WB, but so minor. Love the composition. Hope it does well for you.</td>', 'Wonderful sense of scale. Might be a tad blue in the WB, but so minor. Love the composition. Hope it does well for you.', '2008-01-04 21:35:03.000000', NULL, 1),
(4361733, 627949, 62318, '<td valign="top">Very unique image. I like the fade from color to white. Textures are terrific.</td>', 'Very unique image. I like the fade from color to white. Textures are terrific.', '2008-01-04 21:35:32.000000', NULL, 1),
(4361747, 628172, 62318, '<td valign="top">I love the movement. It turns a normally static ikmage into an exciting one. I also like the shadows.</td>', 'I love the movement. It turns a normally static ikmage into an exciting one. I also like the shadows.', '2008-01-04 21:38:58.000000', NULL, 1),
(4361748, 628349, 66038, '<td valign="top">unfortunate crop</td>', 'unfortunate crop', '2008-01-04 21:38:58.000000', NULL, 1),
(4361752, 626341, 62318, '<td valign="top">eVery open type of style. I think the lone tree give a nice foundation. I might have preferred with just a single building in the backgroud, but otherwise a very lovel shot.</td>', 'eVery open type of style. I think the lone tree give a nice foundation. I might have preferred with just a single building in the backgroud, but otherwise a very lovel shot.', '2008-01-04 21:39:56.000000', NULL, 1),
(4361758, 628323, 62318, '<td valign="top">A striking waterfall. While I like the color, I''m curious did have try a B&amp;W treatment on this, it might pop even better. A splendid location for the shot and composed nicely.</td>', 'A striking waterfall. While I like the color, I''m curious did have try a B&W treatment on this, it might pop even better. A splendid location for the shot and composed nicely.', '2008-01-04 21:41:12.000000', NULL, 1),
(4361762, 628416, 62318, '<td valign="top">Cute, I like the miniature reference here to the wonders of the see. The smoke adds a nice touch.</td>', 'Cute, I like the miniature reference here to the wonders of the see. The smoke adds a nice touch.', '2008-01-04 21:42:10.000000', NULL, 1),
(4361767, 628394, 62318, '<td valign="top">Very nice detailed shot.Very nice color combination and repeated nicely throughout the image.</td>', 'Very nice detailed shot.Very nice color combination and repeated nicely throughout the image.', '2008-01-04 21:43:16.000000', NULL, 1),
(4361771, 628361, 62318, '<td valign="top">Nice overhead shot before the game. Action gets a little lost in the size, but I like the framing of the image as a whole.</td>', 'Nice overhead shot before the game. Action gets a little lost in the size, but I like the framing of the image as a whole.', '2008-01-04 21:44:43.000000', NULL, 1),
(4361774, 627442, 74979, '<td valign="top">great colors to break up the Blahs! of winter; nice sharp center bud</td>', 'great colors to break up the Blahs! of winter; nice sharp center bud', '2008-01-04 21:45:36.000000', NULL, 1),
(4361775, 626108, 62318, '<td valign="top">Nice textures. Actually, I might have preferred the ice without the leaf. There seems to be some really nice things going on under the surface and the leaf just confuses it a little. Still nice take on the pond.</td>', 'Nice textures. Actually, I might have preferred the ice without the leaf. There seems to be some really nice things going on under the surface and the leaf just confuses it a little. Still nice take on the pond.', '2008-01-04 21:45:52.000000', NULL, 1),
(4361776, 627692, 74979, '<td valign="top">icy? hmmm.........</td>', 'icy? hmmm.........', '2008-01-04 21:45:54.000000', NULL, 1),
(4361781, 627410, 74979, '<td valign="top">serene image, despite all the flow...nicely seen &amp; captured.</td>', 'serene image, despite all the flow...nicely seen & captured.', '2008-01-04 21:46:48.000000', NULL, 1),
(4361783, 627201, 62318, '<td valign="top">I love how ice crystals form on plants. The detail is splendid. Since everything is so centered a square crop might have work better for you or pulling in a little. Still. the textures are the draw here and a good one at that.</td>', 'I love how ice crystals form on plants. The detail is splendid. Since everything is so centered a square crop might have work better for you or pulling in a little. Still. the textures are the draw here and a good one at that.', '2008-01-04 21:47:08.000000', NULL, 1),
(4361784, 627616, 74979, '<td valign="top">nice &amp; clear "top of the mtn" shot seen while skiing!  Lovely "feel" to the snow</td>', 'nice & clear "top of the mtn" shot seen while skiing!  Lovely "feel" to the snow', '2008-01-04 21:48:03.000000', NULL, 1),
(4361789, 628105, 74979, '<td valign="top">best of the challenge so far for me, this is so different and very lovely<br/>looks like a beautiful winter flower!</td>', 'best of the challenge so far for me, this is so different and very lovelylooks like a beautiful winter flower!', '2008-01-04 21:49:38.000000', NULL, 1),
(4361793, 628247, 62318, '<td valign="top">I like the movement of the water mixed with the solitary pieces. Might have preferred a less blue tone and a more natural white balance, perhaps even a B&amp;W conversion. Still the intent of the photo is a good one and a joy to look at.</td>', 'I like the movement of the water mixed with the solitary pieces. Might have preferred a less blue tone and a more natural white balance, perhaps even a B&W conversion. Still the intent of the photo is a good one and a joy to look at.', '2008-01-04 21:50:51.000000', NULL, 1),
(4361796, 627522, 74979, '<td valign="top">oh, poignant image.  very creatively done.  i like the plaacement of the bee in the frame.</td>', 'oh, poignant image.  very creatively done.  i like the plaacement of the bee in the frame.', '2008-01-04 21:52:16.000000', NULL, 1),
(4361799, 627972, 74979, '<td valign="top">very nice with sparkle ther eon the droplet.  well timed and seen<br/>nice focus too</td>', 'very nice with sparkle ther eon the droplet.  well timed and seennice focus too', '2008-01-04 21:52:43.000000', NULL, 1);
