(4364546, 628089, 41802, '<td valign="top">Oh this has a dreamy kind of feel.  I am glad you stayed with a blue to give the image a cold feeling.</td>', 'Oh this has a dreamy kind of feel.  I am glad you stayed with a blue to give the image a cold feeling.', '2008-01-05 21:11:06.000000', NULL, 1),
(4364547, 628269, 68947, '<td valign="top">How quaint and picturesque!  Lovely shot!</td>', 'How quaint and picturesque!  Lovely shot!', '2008-01-05 21:11:51.000000', NULL, 1),
(4364548, 627791, 33446, '<td valign="top">This makes me want to go exploring to see it more closely.</td>', 'This makes me want to go exploring to see it more closely.', '2008-01-05 21:12:21.000000', NULL, 1),
(4364549, 626226, 33446, '<td valign="top">You have truly captured the beauty of ice.</td>', 'You have truly captured the beauty of ice.', '2008-01-05 21:13:12.000000', NULL, 1),
