(4364553, 627055, 33446, '<td valign="top">Ice, snowfall, and children bring back wonderful memories.</td>', 'Ice, snowfall, and children bring back wonderful memories.', '2008-01-05 21:15:04.000000', NULL, 1),
(4364561, 626670, 68947, '<td valign="top">What a phenominal shot!  Exquisite focus, shapes, sparkle and background!  Makes me feel COLD and yet warm all at the same time.  Love the title and the star adds a certain.....je ne sais quoi that simply adds to the enchantment of this shot.  Nicely done! <br/> <br/>I''m glad that this has been validated as it proves that the seemingly "impossible" simply means that someone cannot figure out how the heck you could possibly do this within the rules! *grin*</td>', 'What a phenominal shot!  Exquisite focus, shapes, sparkle and background!  Makes me feel COLD and yet warm all at the same time.  Love the title and the star adds a certain.....je ne sais quoi that simply adds to the enchantment of this shot.  Nicely done!  I''m glad that this has been validated as it proves that the seemingly "impossible" simply means that someone cannot figure out how the heck you could possibly do this within the rules! *grin*', '2008-01-05 21:18:48.000000', NULL, 1),
(4364563, 627833, 33446, '<td valign="top">I can almost feel the sharpness of the ice on the leaves.</td>', 'I can almost feel the sharpness of the ice on the leaves.', '2008-01-05 21:18:56.000000', NULL, 1),
(4364570, 627888, 33446, '<td valign="top">The cubes seem to be awkwardly positioned but the border helps to balance the bottom of the photograph.</td>', 'The cubes seem to be awkwardly positioned but the border helps to balance the bottom of the photograph.', '2008-01-05 21:21:58.000000', NULL, 1),
(4364581, 626619, 33446, '<td valign="top">I love the slight curve of the tree.   It appears to be moving towards the stars.</td>', 'I love the slight curve of the tree.   It appears to be moving towards the stars.', '2008-01-05 21:24:33.000000', NULL, 1),
(4364593, 627442, 33446, '<td valign="top">The pastels, the dark green, varying shades of blue, along with the air bubbles make this extremely interesting and fun to view.</td>', 'The pastels, the dark green, varying shades of blue, along with the air bubbles make this extremely interesting and fun to view.', '2008-01-05 21:28:21.000000', NULL, 1),
