(4369897, 626670, 30049, '<td valign="top">This feels like an <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=5112" rel="nofollow" target="_blank">Ursula</a> shot.  Well seen and captured!  I hope you share your star secrets afterwards.  :-)</td>', 'This feels like an  Ursula shot.  Well seen and captured!  I hope you share your star secrets afterwards.  :-)', '2008-01-07 12:46:21.000000', NULL, 1),
(4369926, 628275, 88656, '<td valign="top">very cool</td>', 'very cool', '2008-01-07 12:51:46.000000', NULL, 1),
(4369942, 627939, 30049, '<td valign="top">Uh-oh.  Looks like you let your in-camera meter make the decision on exposure for you.  :)  Actually, with snow it''s quite common in that the camera wants to record the scene as middle grey (neutral).  To compensate you need to intentionally overexpose (use the exposure compensation feature of your camera).  Another option is to set a custom white balance using a grey card (or the palm of your hand if you''re caucasian works in an emergency).<br/> <br/>It''s a very scenic setting overall and I like your choice of positioning to get the water channel coming across the image on a diagonal, and the water is starting near the lower ROT line.<br/> <br/>All JMO of course.  Good luck in the challenge.</td>', 'Uh-oh.  Looks like you let your in-camera meter make the decision on exposure for you.  :)  Actually, with snow it''s quite common in that the camera wants to record the scene as middle grey (neutral).  To compensate you need to intentionally overexpose (use the exposure compensation feature of your camera).  Another option is to set a custom white balance using a grey card (or the palm of your hand if you''re caucasian works in an emergency). It''s a very scenic setting overall and I like your choice of positioning to get the water channel coming across the image on a diagonal, and the water is starting near the lower ROT line. All JMO of course.  Good luck in the challenge.', '2008-01-07 12:55:11.000000', NULL, 1),
(4369943, 628105, 88656, '<td valign="top">love the frost!</td>', 'love the frost!', '2008-01-07 12:55:12.000000', NULL, 1);
